for m in models:
 size=sum(f['bytes'] for f in m['files']);air.append(dict(id=m['id'],name=m['name']+' · AirLLM',description=('Чат и код' if m['thinking'] else 'Для кода · без thinking')+f' · слои на диске · до {size*2.15/1e9+3:.0f} ГБ места · экспериментально',bytes=size,thinking=m['thinking'],installed=False,active=False,hasFiles=False,partial=False,problem=''))
