  await check(await page.locator('#response-mode option[value="1"]').is_disabled(),'Air coder unsupported thinking disabled');await check('Coder' in await page.locator('#model-label').inner_text(),'selected Air coder badge accurate');await page.locator('[data-model="air-coder-7b"] .model-remove').click();await check(await page.evaluate('__sent.at(-1).action==="deleteAirModel"'),'managed Air delete dispatch');await page.locator('#delete-models-all').click();await check(await page.evaluate('__sent.at(-1).action==="deleteAllAirModels"'),'Air delete all scoped to Air catalog')
