  await page.locator('#tab-gguf').click();await check(await page.locator('#tab-gguf').get_attribute('aria-pressed')=='true','GGUF alternative retained');await check(await page.locator('.model-item').count()==0,'catalogs not mixed');await page.locator('#tab-air').click()
  bad=copy.deepcopy(air);bad[4].update(name='<img src=x onerror="window.pwned=1">',problem='unsafe');await page.evaluate('(models)=>receive({type:"catalog",data:{airModels:models}})',bad);await check(await page.evaluate('window.pwned===undefined') and await page.locator('#model-list img').count()==0,'Air metadata escaped');await check(await page.locator('[data-model="air-coder-32b"] .model-pick').is_disabled(),'unsafe model blocked')
