  await check(not errors,'no JavaScript errors');(V/'air-ui.json').write_text(json.dumps({'passed':len(checks),'checks':checks,'scope':'Chromium HTML mocks, not Windows'},ensure_ascii=False,indent=2));print(len(checks),'Air UI checks passed');await b.close()
